import { neon } from '@neondatabase/serverless'

const sql = neon(process.env.DATABASE_URL)

await sql`ALTER TABLE "dreamProfiles" ADD COLUMN IF NOT EXISTS "currentGrade" text`
await sql`ALTER TABLE "dreamProfiles" ADD COLUMN IF NOT EXISTS "applicationYear" integer`
await sql`ALTER TABLE "dreamCountryProfiles" ADD COLUMN IF NOT EXISTS "roadmapSummary" text`
await sql`ALTER TABLE "dreamCountryProfiles" ADD COLUMN IF NOT EXISTS "roadmapSteps" jsonb`
await sql`
  CREATE TABLE IF NOT EXISTS "profileSuggestedActivities" (
    "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "userId" uuid NOT NULL,
    "text" text NOT NULL,
    "status" text NOT NULL DEFAULT 'shortlisted',
    "createdAt" timestamp NOT NULL DEFAULT now()
  )
`

console.log('Added dreamProfiles.currentGrade/applicationYear, dreamCountryProfiles.roadmapSummary/roadmapSteps, and created profileSuggestedActivities.')
